"""The cross-check comparators without Unity (unit P11): on the shipped Simulation Data, and with planted faults.

* X1 on the 109 shipped snapshots is G11 (981/981 columns compose from Value and K2/K3 under double_all);
* the DP8 RpmFirst anchor built from the shipped day snapshots alone reaches G20's 1380/1380;
* X3/X7/DP8/X6 report exactly the item a planted fault touches (the "C#" side is generated by the oracle);
* the check plumbing: statuses, vacuous parts, per-item CSVs.
"""

from __future__ import annotations

import copy
import csv
import math
from dataclasses import replace
from pathlib import Path

import pytest

from tufu_balance import crosscheck as X
from tufu_balance.crosscheck import composition, invariants, rpm
from tufu_balance.model import simcalc as sc
from tufu_balance.model import spawners as sp
from tufu_balance.model.data import load_simulation_data
from tufu_balance.model.snapshots import SimulationStat
from tufu_balance.unity import probes


@pytest.fixture(scope="module")
def env(db):
    return X.Env.load(db)


@pytest.fixture(scope="module")
def shipped(db):
    return load_simulation_data(db)


def _run(early, full, *, mode="free", override=False, records=(), job_dir=Path("."), daily=None):
    manifest = {"job_id": "synthetic", "mode": mode, "override": {"active": override}, "engine": {"counters": {}}}
    trace = None
    if daily is not None:
        from tufu_balance.unity.trace import Trace
        trace = Trace(manifest={}, daily=daily)
    return X.RunData(job_dir, manifest, early, full, [s.tc for s in full], trace, {}, list(records))


def _snaps(lst, snapshots):
    return [X.Snap(lst, i, s, None, []) for i, s in enumerate(snapshots)]


def _bump(x: float, n: int = 1) -> float:
    return float(probes.doubles(format(X.bits(x) + n & (2 ** 64 - 1), "016x"))[0])


def test_x1_on_the_shipped_snapshots_is_g11(env, shipped, tmp_path):
    run = _run(_snaps("Snapshots", shipped.snapshots), _snaps("TimeChunkSnapshots", shipped.time_chunk_snapshots))
    r = composition.check_x1(run, env, tmp_path)
    assert r.status == "pass" and r.items == 109 * 9 * 4 + 109 * 21 * 4  # 9 main + 21 other stats per snapshot
    rows = list(csv.DictReader((tmp_path / "X1.csv").open()))
    assert len(rows) == r.items and all(row["ok"] == "1" for row in rows)
    # one planted 1-ulp TotalValue
    bad = copy.deepcopy(shipped.time_chunk_snapshots)
    st = bad[7].stats[0]
    bad[7].stats[0] = replace(st, total_value=_bump(st.total_value))
    r = composition.check_x1(_run([], _snaps("TimeChunkSnapshots", bad)), env)
    assert r.status == "fail" and r.mismatches == 1
    assert r.examples[0]["field"] == "TotalValue" and r.examples[0]["index"] == 7 and r.examples[0]["ulps"] == 1


def _dp8_records(env, shipped, db):
    """Override records as the C# export writes them, from the oracle (the plumbing under test, not the numbers)."""
    defs = sp.load_spawners(db)
    chain = sc.initial_rpm()
    out = []
    for snap in shipped.time_chunk_snapshots:
        d = snap.time_chunk_index
        boss = sp.boss_for_location(snap.location, defs)
        kw = {"current_boss": boss.spawner_id if boss else None}
        enc = lambda data: [[env.runtime_id(sid), "".join(probes.dhex(v) for v in rpm._oracle_fields(x))]
                            for sid, x in data.items()]
        gpm = sc.calculate_spawner_data(env.ctx, rpm._shipped_state(env, snap, d, d), True, **kw)
        state = rpm._shipped_state(env, snap, d, d - 1)
        rf = sc.calculate_spawner_data(env.ctx, state, True, **kw)
        chain, _, _ = sc.calculate_rpm_value_time_chunk(env.ctx, state, rpm=chain)
        out.append({"day": d, "location": snap.location, "current_boss": env.runtime_id(boss.spawner_id) if boss else None,
                    "crosscheck_dp8": {"day": d, "gpm": enc(gpm), "rpm_first": {
                        "stats": [[k, probes.dhex(v)] for k, v in state.stats.items()], "spawners": enc(rf),
                        "rpm": [[k, probes.dhex(v)] for k, v in chain.items()]}}})
    return out


@pytest.mark.slow
def test_dp8_anchor_and_planted_faults(env, shipped, db, tmp_path):
    records = _dp8_records(env, shipped, db)
    run = _run([], [], mode="checkpoint", override=True, records=records)
    r = rpm.check_dp8(run, env, tmp_path)
    assert r.status == "pass", r.examples
    assert (r.counts["states"], r.counts["g20_cells"], r.counts["g20_matches"]) == (46, 1380, 1380)
    assert r.counts["fields_max_rel_diff"] == 0.0
    # a field off by 1e-9 relative, a spawner missing, one RPM cell off
    bad = copy.deepcopy(records)
    rid, hexes = bad[10]["crosscheck_dp8"]["gpm"][3]
    values = probes.doubles(hexes)
    values[1] *= 1 + 1e-9
    bad[10]["crosscheck_dp8"]["gpm"][3] = [rid, "".join(probes.dhex(v) for v in values)]
    del bad[20]["crosscheck_dp8"]["rpm_first"]["spawners"][0]
    k, h = bad[30]["crosscheck_dp8"]["rpm_first"]["rpm"][1]
    bad[30]["crosscheck_dp8"]["rpm_first"]["rpm"][1] = [k, probes.dhex(probes.doubles(h)[0] * 2 + 1)]
    r = rpm.check_dp8(_run([], [], mode="checkpoint", override=True, records=bad), env)
    found = sorted((e["table"], e.get("day"), e.get("worst_field") or e.get("present") or e.get("stat_name")) for e in r.examples)
    assert r.mismatches == 3, found
    assert found[0][:2] == ("DP8", records[10]["day"]) and found[0][2] == "fight_time"
    assert found[1][:2] == ("DP8", records[20]["day"]) and found[1][2] == "oracle_only"
    assert found[2][:2] == ("DP8_rpm", records[30]["day"])


def _gpm_run(env, shipped, order_lag: int):
    """Day snapshots whose CurrentGpm is the oracle's own RpmFirst chain on their state (current health full)."""
    out, rpm_ = [], sc.initial_rpm()
    for i, snap in enumerate(shipped.time_chunk_snapshots[:12]):
        s = X.Snap("TimeChunkSnapshots", i, replace(snap, time_chunk_index=i), None, [])
        rpm_ = rpm._rpm(env, rpm.day_state(env, s, i - order_lag), rpm_)
        stats = [replace(st, current_gpm=rpm_.get(st.key, 0.0)) for st in snap.stats]
        out.append(X.Snap("TimeChunkSnapshots", i, replace(snap, time_chunk_index=i, stats=stats), None, []))
    return out


def test_x3_x7_follow_rpm_first_and_catch_a_planted_cell(env, shipped):
    full = _gpm_run(env, shipped, 1)
    for check in (rpm.check_x3, rpm.check_x7):
        r = check(_run([], full), env)
        assert r.status == "pass" and r.counts["bit_equal"] == r.items == 12 * 30
    assert rpm.check_x7(_run([], full), env).counts["modifier_first_cells_off"] > 0
    st = full[5].snapshot.stats[0]
    full[5].snapshot.stats[0] = SimulationStat(st.key, st.value, st.stats_from_features_flat, st.percent_multiplier,
                                               st.total_flat_value, st.total_value, st.current_gpm * (1 + 1e-9))
    r = rpm.check_x3(_run([], full), env)
    assert r.mismatches >= 1 and r.examples[0]["time_chunk_index"] == 5
    # ModifierFirst data fails RpmFirst's X7
    r = rpm.check_x7(_run([], _gpm_run(env, shipped, 0)), env)
    assert r.status == "fail"
    assert rpm.check_x3(_run([], [], override=True), env).status == "vacuous"


def test_x6_clock_day_list_and_values(env, shipped, tmp_path):
    base = invariants.base_values(env)
    days = []
    for i in range(6):
        s = shipped.time_chunk_snapshots[0]
        stats = [replace(st, value=base.get(st.key, 0.0)) for st in s.stats]
        days.append(X.Snap("TimeChunkSnapshots", i, replace(s, time_chunk_index=i, total_playtime=float(1440 * i + 4),
                                                             stats=stats), {"exported_index": [0, 1, 2, 3, 4, 5][i]}, []))
    daily = [{"day": i, "playtime": 0.0, "total_playtime": 1440.0 * i, "clears": 0} for i in range(6)]
    r = invariants.check_x6(_run([], days, daily=daily), env, tmp_path)
    assert r.status == "pass", r.examples
    assert set(r.vacuous) == {"values_rewards", "charges", "dafc", "unlocks"}
    days[3].snapshot.stats[2] = replace(days[3].snapshot.stats[2], value=days[3].snapshot.stats[2].value + 1.0)
    days[4] = replace(days[4], snapshot=replace(days[4].snapshot, total_playtime=float(1440 * 5)))
    r = invariants.check_x6(_run([], days, daily=daily), env)
    kinds = sorted(e["invariant"] for e in r.examples)
    assert kinds == ["time_chunk", "values"], r.examples


def test_statuses_and_csv(tmp_path):
    c = X.Check("T", "t", ("a",))
    assert c.result(tmp_path).status == "vacuous"
    c.item(True, a=1)
    c.vacuous_part("p", "why")
    r = c.result(tmp_path)
    assert (r.status, r.items, r.vacuous) == ("pass", 1, {"p": "why"})
    c.item(False, a=2)
    r = c.result(tmp_path)
    assert r.status == "fail" and r.examples == [{"table": "T", "a": 2, "ok": 0}]
    assert (tmp_path / "T.csv").read_text() == "a,ok\n1,1\n2,0\n"
    assert X.rel_diff(1.0, 1.0) == 0.0 and X.rel_diff(math.nan, math.nan) == 0.0 and X.rel_diff(1.0, math.inf) == math.inf
    assert X.forecast_value(1, 100.0, 0.5, 2.0) == 300.0 and X.forecast_value(3, 4.0, 0.5, 2.0) == 4.0


def test_x2_weapon_order_and_override_scope(env, shipped):
    from tufu_balance.crosscheck import dps

    s = X.Snap("TimeChunkSnapshots", 0, copy.deepcopy(shipped.time_chunk_snapshots[0]),
               {"unlocked_weapon_slots": 4, "unlocked_armor_slots": 4}, [])
    calc, defense = dps.recompute(s, env, -1)
    s.snapshot.dps_data[:] = calc
    s.snapshot.defense_data[:] = defense
    assert dps.check_x2(_run([], [s]), env).status == "pass"
    s.snapshot.dps_data.reverse()
    r = dps.check_x2(_run([], [s]), env)
    assert r.status == "fail" and r.mismatches == 1 and r.examples[0]["weapon_type"] == "order"
    # C4's slow-tick caches need not equal the item-derived ones; forced snapshots still must.
    early = replace(s, list="Snapshots", snapshot=replace(s.snapshot, playtime=1.0))
    r = dps.check_x2(_run([early], [], mode="checkpoint", override=True), env)
    assert r.status == "vacuous" and r.counts["override_slow_tick_snapshots"] == 1
    assert "override_slow_tick" in r.vacuous
    assert dps.check_x2(_run([], [s], mode="checkpoint", override=True), env).status == "fail"


def _text_job(path, *, defect=True, extra_fault=False):
    import hashlib
    import json
    from tufu_balance.unity import schema, simio

    path.mkdir()
    want = float.fromhex("0x1.9000000000001p+6")  # 100 + 1 ulp; its .15g text is 100
    stat = {"Key": 1, "Value": want, "StatsFromFeaturesFlat": 0.0, "PercentMultiplier": 1.0,
            "TotalFlatValue": want, "TotalValue": want, "CurrentGpm": 0.0}
    snap = {"Playtime": 0.0, "TotalPlaytime": 0.0, "Location": 1, "TimeChunkIndex": 0,
            "Stats": [stat], "Items": [], "DpsData": [], "DefenseData": []}
    expected = {"Snapshots": [snap], "TimeChunkSnapshots": []}
    actual = copy.deepcopy(expected)
    actual["Snapshots"][0]["Stats"][0]["TotalFlatValue"] = float(format(want, ".15g")) if defect else _bump(want)
    if extra_fault:
        actual["Snapshots"][0]["Stats"][0]["CurrentGpm"] = 1.0  # not compared by X1
    body = json.dumps(actual).encode()
    (path / X.SIM_FILE).write_bytes(body)
    entry = {"sha256": hashlib.sha256(body).hexdigest(), "bytes": len(body), **simio.bits_digest(expected)}
    manifest = {"schema": schema.MANIFEST_SCHEMA, "job_id": "text", "exit_code": 0,
                "export": {"schema": schema.EXPORT_SCHEMA, "files": {X.SIM_FILE: entry}}}
    (path / "manifest.json").write_text(json.dumps(manifest))
    return path


@pytest.mark.parametrize("defect,extra_fault,checks,repairs,confirmed", [
    (True, False, ("X1",), 1, True),
    (False, False, ("X1",), 0, False),
    (True, True, ("X1", "X3"), 1, False),
    (True, False, ("X3",), 0, False),
])
def test_text_repair_requires_the_known_defect_and_the_complete_digest(
        db, tmp_path, defect, extra_fault, checks, repairs, confirmed):
    import json

    job = _text_job(tmp_path / "job", defect=defect, extra_fault=extra_fault)
    results = X.run_checks(job, db, checks=checks)
    summary = json.loads((job / X.CSV_DIR / "summary.json").read_text())
    assert summary["export_text"]["repairs"] == repairs
    assert summary["export_text"]["confirmed"] is confirmed
    assert all(r.status == ("pass" if confirmed else "fail") for r in results.values())
    assert all("export_text.csv" in r.csv for r in results.values())
    rows = list(csv.DictReader((job / X.CSV_DIR / "export_text.csv").open()))
    assert [int(row["ok"]) for row in rows] == [int(confirmed)]
    if not defect:
        assert results["X1"].counts.get("text_repaired", 0) == 0


def _falling_rpm_days(env, shipped):
    out, chain = [], sc.initial_rpm()
    for i, snap in enumerate((shipped.time_chunk_snapshots[-1], shipped.time_chunk_snapshots[0])):
        s = X.Snap("TimeChunkSnapshots", i, replace(snap, time_chunk_index=i), None, [])
        chain = rpm._rpm(env, rpm.day_state(env, s, i - 1), chain)
        out.append(replace(s, snapshot=replace(s.snapshot, stats=[
            replace(st, current_gpm=chain.get(st.key, 0.0)) for st in s.snapshot.stats])))
    return out


def test_rpm_retains_previous_maximum_when_the_state_weakens(env, shipped, db, monkeypatch):
    with X.mono_arithmetic():
        full = _falling_rpm_days(env, shipped)
        for check in (rpm.check_x3, rpm.check_x7):
            r = check(_run([], full), env)
            assert r.status == "pass", r.examples
            assert r.counts["running_max_cells"] > 0 and "running_max" not in r.vacuous
        # Resetting the C# chain produces a real failure on the second day.
        state = rpm.day_state(env, full[1], 0)
        fresh = rpm._rpm(env, state, sc.initial_rpm())
        bad = copy.deepcopy(full)
        bad[1].snapshot.stats[:] = [replace(st, current_gpm=fresh.get(st.key, 0.0)) for st in bad[1].snapshot.stats]
        assert rpm.check_x3(_run([], bad), env).status == "fail"
        assert rpm.check_x7(_run([], bad), env).status == "fail"

        synthetic = replace(shipped, time_chunk_snapshots=[s.snapshot for s in full])
        records = _dp8_records(env, synthetic, db)
        monkeypatch.setattr(rpm, "load_simulation_data", lambda con: synthetic)
        r = rpm.check_dp8(_run([], [], mode="checkpoint", override=True, records=records), env)
        assert r.status == "pass", r.examples
        assert r.counts["running_max_cells"] > 0 and "running_max" not in r.vacuous
        records[1]["crosscheck_dp8"]["rpm_first"]["rpm"] = [[k, probes.dhex(v)] for k, v in fresh.items()]
        assert rpm.check_dp8(_run([], [], mode="checkpoint", override=True, records=records), env).status == "fail"


def test_x5_oracle_set_excludes_cleared_dafc_and_catches_a_wrong_signature(env, shipped, tmp_path):
    from tufu_balance.crosscheck import eligibility
    from tufu_balance.unity import trace

    snap = next(s for s in shipped.time_chunk_snapshots if s.time_chunk_index == 7)
    s = X.Snap("TimeChunkSnapshots", 0, snap,
               {"unlocked_weapon_slots": 4, "unlocked_armor_slots": 4, "current_health": 0.0}, [])
    with X.mono_arithmetic():
        state = eligibility.planning_state(env, s)
        assert state.current_health == 0.0
        plain = sc.calculate_spawner_data(env.ctx, state, False)
        sid = next(sid for sid, x in plain.items() if x.spawner.d.dafc)
        filtered = sc.calculate_spawner_data(env.ctx, state, False, sc.BotFilter(cleared_dafc=frozenset({sid})))
        assert sid not in filtered and set(plain) - set(filtered) == {sid}
        row = {"day": 7, "eligible_count": len(filtered),
               "eligible_signature": trace.set_signature([env.runtime_id(sid) for sid in filtered])}
        run = _run([], [s], daily=[row])
        run.trace.events.append({"type": "first_kill", "day": 6, "spawner": env.runtime_id(sid)})
        r = eligibility.check_x5(run, env, tmp_path)
        assert r.status == "pass" and r.counts["dafc_cleared_excluded"] == 1
        assert r.counts["missing_health_states"] == 1 and "missing_health" not in r.vacuous
        row["eligible_signature"] = "0" * 64
        r = eligibility.check_x5(run, env)
        assert r.status == "fail" and r.mismatches == 1
        run.manifest["override"]["active"] = True
        assert eligibility.check_x5(run, env).vacuous.keys() == {"override"}


def test_x5_planning_uses_current_day_modifiers(env, shipped):
    from tufu_balance.crosscheck import dps, eligibility
    from tufu_balance.unity import trace
    from tufu_balance.model.enums import StatType

    snap = next(s for s in shipped.time_chunk_snapshots if s.time_chunk_index == 7)
    snap = replace(snap, stats=[replace(st, value=st.value + 10.0) if st.key == 8 else st for st in snap.stats])
    s = X.Snap("TimeChunkSnapshots", 0, snap, {"unlocked_weapon_slots": 4, "unlocked_armor_slots": 4}, [])
    with X.mono_arithmetic():
        state = eligibility.planning_state(env, s)
        stats = dps.forecast_stats(snap, env, s.tc - 1)
        items = dps.item_entries(s, env)
        lag = replace(state, stats=stats,
                      dps_data=dict(sc.calculate_dps_data(env.ctx, stats, items, 4, s.tc)),
                      defense_data=dict(sc.calculate_defense_data(env.ctx, stats, items, 4, s.tc)))
        data = sc.calculate_spawner_data(env.ctx, state, False)
        old = sc.calculate_spawner_data(env.ctx, lag, False)
        sid = next(sid for sid, x in data.items() if sid in old and not x.spawner.d.dafc
                   and 0.0 < x.fight_time < old[sid].fight_time)
        x = data[sid]
        scale = 300.0 / ((x.fight_time + old[sid].fight_time) / 2.0)
        target = replace(x.spawner, stats=tuple((k, v * scale if k == int(StatType.Health) else v)
                                               for k, v in x.spawner.stats))
        test_env = replace(env, ctx=replace(env.ctx, spawners=[target]))
        current_ids = sc.calculate_spawner_data(test_env.ctx, state, False)
        lag_ids = sc.calculate_spawner_data(test_env.ctx, lag, False)
        assert set(current_ids) == {sid} and not lag_ids
        row = {"day": 7, "eligible_count": 1, "eligible_signature": trace.set_signature([env.runtime_id(sid)])}
        r = eligibility.check_x5(_run([], [s], daily=[row]), test_env)
        assert r.status == "pass" and r.items == 1


@pytest.mark.parametrize("fault", ["same_T", "backward_P", "daily_clock", "sequence", "trimmed", "exported_index"])
def test_x6_planted_clock_and_day_list_faults(env, shipped, fault):
    days = [X.Snap("TimeChunkSnapshots", i, replace(shipped.time_chunk_snapshots[0], time_chunk_index=i,
                total_playtime=float(1440 * i), playtime=float(i)), {"exported_index": i}, []) for i in range(3)]
    daily = [{"day": i, "playtime": float(i), "total_playtime": float(1440 * i)} for i in range(3)]
    run = _run([], days, daily=daily)
    if fault == "same_T":
        days[1] = replace(days[1], snapshot=replace(days[1].snapshot, total_playtime=0.0))
    elif fault == "backward_P":
        days[2] = replace(days[2], snapshot=replace(days[2].snapshot, playtime=0.0))
    elif fault == "daily_clock":
        daily[2]["total_playtime"] = 0.0
    elif fault == "sequence":
        days[1] = replace(days[1], snapshot=replace(days[1].snapshot, time_chunk_index=0))
    elif fault == "trimmed":
        run.exported_days.pop()
    elif fault == "exported_index":
        days[1].ext["exported_index"] = 7
    c = X.Check("X6", "guards", invariants.COLUMNS)
    invariants._clock(c, run)
    invariants._day_list(c, run)
    r = c.result()
    assert r.status == "fail" and r.mismatches >= 1
    assert r.examples[0]["invariant"] == ("clock" if fault in ("same_T", "backward_P", "daily_clock") else "day_list")


def test_x6_time_chunk_uses_float32_quotient(env, shipped):
    from tufu_balance.model.f32 import f32

    # Binary32 T immediately below this day boundary divides to just below an integer in double,
    # but rounds to the integer when stored as float32 (the C# RebuildDayIndex path).
    d = 600001  # deliberately beyond the shipped days, where integer minute totals lose precision
    total = float(f32(d * 1440.0))
    assert total / 1440.0 < d and float(f32(total / 1440.0)) == d
    s = X.Snap("Snapshots", 0, replace(shipped.time_chunk_snapshots[0], time_chunk_index=d, total_playtime=total), None, [])
    c = X.Check("X6", "TC", invariants.COLUMNS)
    invariants._time_chunk(c, _run([s], []), env)
    assert c.result().status == "pass"


def test_armor_tie_and_forecast_multiplication_order():
    from types import SimpleNamespace

    a = SimpleNamespace(type=0, resist=0.0)
    b = SimpleNamespace(type=1, resist=0.5)
    coverage = {}
    assert X.mono_best_armor_against_dps(SimpleNamespace(armors=[a, b]),
                SimpleNamespace(dps_cache={0: 1.0, 1: 2.0}), coverage=coverage) is a
    assert coverage["armor_best_ties"] == 1
    value, k2, k3 = 0.1, 0.2, 1.3
    game = X.forecast_value(1, value, k2, k3)
    assert X.same(game, (k3 * (1.0 + k2)) * value)
    assert not X.same(game, (value * (1.0 + k2)) * k3)


def test_x4_c8_format_report_and_one_ulp_fault(env, shipped, tmp_path):
    import json
    from tufu_balance.crosscheck import bake

    run = _run(_snaps("Snapshots", shipped.snapshots), _snaps("TimeChunkSnapshots", shipped.time_chunk_snapshots),
               job_dir=tmp_path)
    oracle = bake.oracle_bake(run, env)
    rows = []
    for sid, (_, result) in oracle.items():
        row = {"id": env.runtime_id(sid), "registered": True}
        if isinstance(result, bake.B.BakeError):
            row["error"] = str(result)
        else:
            row["report"] = {"NewHealth": probes.dhex(result.new_health), "NewDamage": probes.dhex(result.new_damage)}
        rows.append(row)
    path = tmp_path / bake.REPORT
    path.write_text(json.dumps({"snapshots": "run", "spawners": rows}))
    r = bake.check_x4(run, env, tmp_path)
    assert r.status == "pass" and r.items == 717 and r.counts["report_missing"] == 0
    row = next(r for r in rows if "report" in r and math.isfinite(probes.doubles(r["report"]["NewHealth"])[0]))
    row["report"]["NewHealth"] = probes.dhex(_bump(probes.doubles(row["report"]["NewHealth"])[0]))
    path.write_text(json.dumps({"snapshots": "run", "spawners": rows}))
    r = bake.check_x4(run, env)
    assert r.status == "fail" and r.mismatches == 1 and r.examples[0]["spawner"] == row["id"]


def test_x2_slow_tick_basis_checks_own_postfight_stats(env, shipped):
    from tufu_balance.crosscheck import dps

    snap = copy.deepcopy(shipped.snapshots[1])
    s = X.Snap("Snapshots", 1, snap, {"unlocked_weapon_slots": 1, "unlocked_armor_slots": 1}, [])
    basis = dps.forecast_stats(snap, env, s.tc)
    s.slow_tick_basis = basis
    calc, defense = dps.recompute(s, env, s.tc)
    snap.dps_data[:], snap.defense_data[:] = calc, defense
    run = _run([s], [], daily=[{"clears": 1}])
    good = dps.check_x2(run, env)
    assert good.status == "pass" and good.items == 10 + len(basis)
    previous = dps.forecast_stats(shipped.snapshots[0], env, s.tc)
    for bad_basis in ({**basis, 8: basis[8] + 1.0}, previous, None,
                      {k: v for k, v in basis.items() if k != 8}):
        s.slow_tick_basis = bad_basis
        bad = dps.check_x2(run, env)
        assert bad.status == "fail" and bad.mismatches > 0
        assert bad.vacuous == good.vacuous
    # A cache computed from pre-fight / previous-tick / wrong stats must fail even with a good basis.
    s.slow_tick_basis = basis
    for wrong in (previous, {**basis, 8: basis[8] + 1.0}, {**basis, 8: basis[16], 16: basis[8]}):
        snap.dps_data[:], snap.defense_data[:] = dps.recompute(s, env, s.tc, stats=wrong)
        bad = dps.check_x2(run, env)
        assert bad.status == "fail" and any(e["kind"] != "cache_basis" for e in bad.examples)


def test_shipped_day_zero_dps_uses_the_recorded_postfight_stats(env, shipped):
    from tufu_balance.crosscheck import dps

    # Day zero avoids the later K/slot/evolution ambiguity. One weapon before island 2,
    # two afterwards; every early snapshot has exactly the recorded post-reward cache.
    early = [s for s in shipped.snapshots if s.time_chunk_index == 0]
    assert len(early) == 25
    previous_off = 0
    for i, snap in enumerate(early):
        s = X.Snap("Snapshots", i, snap,
                   {"unlocked_weapon_slots": 1 if snap.location == 1 else 2, "unlocked_armor_slots": 1}, [])
        calc, _ = dps.recompute(s, env, 0)
        assert all(X.same(a, b) for (_, a), (_, b) in zip(calc, snap.dps_data)), i
        if i:
            before = dps.forecast_stats(early[i - 1], env, 0)
            old, _ = dps.recompute(s, env, 0, stats=before)
            previous_off += any(not X.same(a, b) for (_, a), (_, b) in zip(old, snap.dps_data))
    assert previous_off == 15


def test_x6_rounds_each_modifier_write_and_keeps_double_base(env, shipped):
    from types import SimpleNamespace
    from tufu_balance.model.f32 import f32

    big, small = "big", "small"
    spawners = [SimpleNamespace(spawner_id=sid, d=SimpleNamespace(count=1),
                   stat_rewards=[SimpleNamespace(stat_type=8, value=value)])
                for sid, value in ((big, 16777216.0), (small, 1.0))]
    test_env = SimpleNamespace(ctx=replace(env.ctx, spawners=spawners), con=env.con,
                               runtime_id=lambda sid: sid, spawner_id=lambda rid: rid)
    base = invariants.base_values(env)
    day0 = shipped.time_chunk_snapshots[0]
    days = []
    for i in range(3):
        # Two writes 2**24, 1 in the slow phase lose 1; the next fast flush also loses 1.
        # BaseValue 3.4 and the independent probe modifier must retain their double composition.
        value = float(f32(0.1)) + (16777216.0 if i else 0.0)
        stats = [replace(st, value=value if st.key == 8 else base.get(st.key, 0.0)) for st in day0.stats]
        days.append(X.Snap("TimeChunkSnapshots", i, replace(day0, stats=stats, time_chunk_index=i), None, []))
    run = _run([], days, daily=[{"clears": 3}])
    run.manifest["job"] = {"engine_probe": {"grant_flat": {"8": 0.1}},
                           "config_overrides": {"FastTickStartChunkOffset": 1}}
    run.trace.events = [{"type": "slow_fight", "day": 0, "cleared": True, "spawner": rid}
                        for rid in (big, small)]
    run.digests = {0: {}, 1: {"charges_closed.day": "0", "charges_closed.big": "1", "charges_closed.small": "1"},
                   2: {"charges_closed.day": "1", "charges_closed.small": "1"}}
    def check():
        c = X.Check("X6", "values", invariants.COLUMNS)
        invariants._values(c, run, test_env)
        return c.result()
    good = check()
    assert good.status == "pass" and good.counts["values_exact_cells"] == 90
    # A double-sum oracle or a missing slow write must fail this independent literal fixture.
    st = next(st for st in days[2].snapshot.stats if st.key == 8)
    days[2].snapshot.stats[days[2].snapshot.stats.index(st)] = replace(st, value=st.value + 1.0)
    bad = check()
    assert bad.status == "fail" and bad.mismatches == 1
    days[2].snapshot.stats[days[2].snapshot.stats.index(next(x for x in days[2].snapshot.stats if x.key == 8))] = st
    run.trace.events.pop()
    assert check().status == "fail"


@pytest.mark.parametrize("pending", [0.0, 1.0])
@pytest.mark.parametrize("clears", [0, 1])
def test_x6_rejects_pending_fast_rewards_at_forced_snapshots(env, shipped, pending, clears):
    base = invariants.base_values(env)
    snap = shipped.time_chunk_snapshots[0]
    snap = replace(snap, stats=[replace(st, value=base.get(st.key, 0.0)) for st in snap.stats])
    run = _run([], _snaps("TimeChunkSnapshots", [snap]))
    run.manifest["engine"]["counters"]["clears"] = clears
    run.digests = {0: {"fast.stat.8": "Devoured,0,0," + probes.fhex(pending)}}
    c = X.Check("X6", "values", invariants.COLUMNS)
    invariants._values(c, run, env)
    result = c.result()
    assert result.mismatches == int(pending != 0.0)
    assert result.status == ("fail" if pending else "pass")
    if pending:
        assert result.examples[0]["where"] == "day 0 fast.stat.8"
        assert result.examples[0]["detail"] == "forced snapshot follows fast reward flush"
